def validate_search_space(experiment_config):
    """
    check whether the search space is valid
    """
    if 'searchSpacePath' not in experiment_config:
        return True
    if not os.path.exists(experiment_config['searchSpacePath']):
        return False
    return True


def validate_trial_config(experiment_config):
    """
    check whether the trial config is valid
    """
    if 'trial' not in experiment_config:
        return True
    if 'codeDir' not in experiment_config['trial']:
        return False
    if not os.path.exists(experiment_config['trial']['codeDir']):
        return False
    return True


def validate_experiment(experiment_config):
    """
    check whether the experiment config is valid
    """
    if not validate_customized_file(experiment_config, 'tuner'):
        return False
    if not validate_customized_file(experiment_config, 'assessor'):
        return False
    if not validate_customized_file(experiment_config, 'advisor'):
        return False
    if not validate_search_space(experiment_config):
        return False
    if not validate_trial_config(experiment_config):
        return False
    return True


